// Enforce required preconditions: begin() must have succeeded and latch interval honored
int begun = FUZZ_GET_ATTR_INT(neo, "begun");
if (!begun) { FUZZ_BAIL(); }
// Avoid blocking excessively: only call show() if canShow() is true
if (!neo->canShow()) { FUZZ_BAIL(); }
// At this point, pixel data (if any) will be transmitted
neo->show();

// Obtain the raw pixel buffer pointer; do not dereference or assume non-null
uint8_t *p = neo->getPixels();
(void)p;

uint8_t x = (uint8_t)(*FUZZ_PARAM(unsigned int));
uint8_t y = Adafruit_NeoPixel::sine8(x);
(void)y;

uint8_t x = (uint8_t)(*FUZZ_PARAM(unsigned int));
uint8_t y = Adafruit_NeoPixel::gamma8(x);
(void)y;

// Exercise both RGB and RGBW packers
unsigned int mode = *FUZZ_PARAM(unsigned int) & 1;
uint8_t r = (uint8_t)(*FUZZ_PARAM(unsigned int));
uint8_t g = (uint8_t)(*FUZZ_PARAM(unsigned int));
uint8_t b = (uint8_t)(*FUZZ_PARAM(unsigned int));
if (mode == 0) {
    uint32_t c = Adafruit_NeoPixel::Color(r, g, b);
    (void)c;
} else {
    uint8_t w = (uint8_t)(*FUZZ_PARAM(unsigned int));
    uint32_t c = Adafruit_NeoPixel::Color(r, g, b, w);
    (void)c;
}

